// Standardwerte: hier den eigenen Verkäufer und die Bankverbindung eintragen.
const VERKAEUFER = {
  name: 'Muster GmbH',
  vatId: 'DE123456789',
  address: { line1: 'Musterstraße 1', postalCode: '20095', city: 'Hamburg', countryCode: 'DE' },
};
const IBAN = 'DE02120300000000202051';
const ZAHLUNGSZIEL_TAGE = 14;

// Formularfelder in die Rechnungsdaten übersetzen.
const f = $input.first().json.body ?? {};
const zahl = (v) => Number(String(v ?? '').trim().replace(/\./g, '').replace(',', '.'));
const positionen = [1, 2, 3]
  .filter((i) => String(f['p' + i + '_text'] ?? '').trim() !== '')
  .map((i) => ({
    name: String(f['p' + i + '_text']).trim(),
    quantity: zahl(f['p' + i + '_menge'] || '1'),
    unitPriceNet: zahl(f['p' + i + '_preis']),
    vatRatePercent: zahl(f['p' + i + '_ust'] || '19'),
  }));
const eingabe = {
  invoiceNumber: String(f.nummer ?? '').trim() || undefined,
  issueDate: String(f.datum ?? '').trim() || undefined,
  buyer: {
    name: String(f.name ?? '').trim(),
    address: {
      line1: String(f.strasse ?? '').trim(),
      postalCode: String(f.plz ?? '').trim(),
      city: String(f.ort ?? '').trim(),
      countryCode: (String(f.land ?? '').trim() || 'DE').toUpperCase(),
    },
  },
  lines: positionen,
};
const tag = (d) => d.toISOString().slice(0, 10);
const heute = tag(new Date());
const faellig = tag(new Date(Date.now() + ZAHLUNGSZIEL_TAGE * 864e5));
const r2 = (n) => Math.round(n * 100) / 100;

const lines = (eingabe.lines ?? []).map((l) => {
  const quantity = Number(l.quantity ?? 1);
  const unitPriceNet = Number(l.unitPriceNet ?? 0);
  const vatRatePercent = Number(l.vatRatePercent ?? 19);
  return { name: l.name, quantity, unitCode: l.unitCode ?? 'C62', unitPriceNet, vatRatePercent, lineNetAmount: r2(quantity * unitPriceNet) };
});
if (lines.length === 0) throw new Error('Mindestens eine Position ausfüllen.');

const gruppen = {};
for (const l of lines) {
  const g = (gruppen[l.vatRatePercent] ??= { ratePercent: l.vatRatePercent, basisAmount: 0, categoryCode: l.vatRatePercent > 0 ? 'S' : 'Z' });
  g.basisAmount = r2(g.basisAmount + l.lineNetAmount);
}
const vatBreakdown = Object.values(gruppen).map((g) => ({ ...g, taxAmount: r2((g.basisAmount * g.ratePercent) / 100) }));
const totalNet = r2(lines.reduce((s, l) => s + l.lineNetAmount, 0));
const totalVat = r2(vatBreakdown.reduce((s, g) => s + g.taxAmount, 0));
const invoiceNumber = eingabe.invoiceNumber ?? 'RE-' + heute.replaceAll('-', '') + '-' + String(Date.now()).slice(-4);

const invoice = {
  invoiceNumber,
  issueDate: eingabe.issueDate ?? heute,
  dueDate: eingabe.dueDate ?? faellig,
  seller: eingabe.seller ?? VERKAEUFER,
  buyer: eingabe.buyer,
  payment: { iban: eingabe.iban ?? IBAN, reference: invoiceNumber },
  lines,
  vatBreakdown,
  totalNet,
  totalVat,
  totalGross: r2(totalNet + totalVat),
};
return [{ json: { invoice, filename: invoiceNumber + '.pdf' } }];
